parameters.jsCode:
// Phase 3c — build Plane card body from Krayin response + booking ctx.
// Skip on RESCHEDULE (already have a card) and CANCEL (don't make a new one).
const krayin = $input.first().json;
const booking = $('Normalize booking').first().json;

// Only fire on BOOKING_CREATED — skip otherwise (returns no items)
if (booking.trigger !== 'BOOKING_CREATED') return [];

// Lead must have been created/updated successfully
if (!krayin?.success || !krayin?.lead_id) return [];

// Skip silently if Plane isn't configured (env var blank)
if (!$env.PLANE_API_TOKEN || !$env.PLANE_PROJECT_ID || !$env.PLANE_WORKSPACE_SLUG) return [];

// target_date from start_time (YYYY-MM-DD)
let targetDate = '';
try { targetDate = (booking.start_time || '').slice(0, 10); } catch {}

const descLines = [
  `<p><strong>Booking:</strong> ${booking.event_title}</p>`,
  `<p><strong>When:</strong> ${booking.start_time || 'tba'}</p>`,
  booking.join_url ? `<p><strong>Join:</strong> <a href="${booking.join_url}">${booking.join_url}</a></p>` : '',
  booking.email ? `<p><strong>Invitee:</strong> ${booking.name || booking.email} &lt;${booking.email}&gt;</p>` : '',
  booking.company ? `<p><strong>Company:</strong> ${booking.company}</p>` : '',
  booking.phone ? `<p><strong>Phone:</strong> ${booking.phone}</p>` : '',
  booking.notes ? `<p><strong>Notes:</strong><br>${booking.notes.replace(/\n/g, '<br>')}</p>` : '',
  `<p><a href="https://crm.underwings.org/admin/leads/view/${krayin.lead_id}">Open lead in Krayin →</a></p>`,
].filter(Boolean).join('');

return [{
  json: {
    lead_id: krayin.lead_id,
    plane_url: `${$env.PLANE_BASE_URL}/api/v1/workspaces/${$env.PLANE_WORKSPACE_SLUG}/projects/${$env.PLANE_PROJECT_ID}/work-items/`,
    body: {
      name: `Discovery: ${booking.name || booking.email}${booking.company ? ' / ' + booking.company : ''}`,
      description_html: descLines,
      priority: 'medium',
      target_date: targetDate || undefined,
      external_id: booking.booking_uid,
      external_source: 'calcom',
    },
  },
}];

